DROP SCHEMA IF EXISTS t2s_xsyn2 CASCADE;
CREATE SCHEMA t2s_xsyn2;
CREATE VIEW t2s_xsyn2.outlets AS SELECT branch_id AS outlet_key, branch_code AS outlet_ref, branch_name AS outlet_title, branch_type AS outlet_variety, parent_branch_id AS parent_outlet_key, province AS region, district AS area, opened_date AS started_day, closed_date AS ended_day, is_active AS is_active FROM t2s.branches;
CREATE VIEW t2s_xsyn2.workers AS SELECT employee_id AS worker_key, employee_no AS worker_no, first_name AS first_title, last_name AS last_title, full_name AS full_title, branch_id AS outlet_key, department_code AS department_ref, department_name AS department_title, position_code AS position_ref, position_name AS position_title, manager_id AS manager_key, hire_date AS hire_day, termination_date AS termination_day, employment_status AS job_condition FROM t2s.employees;
CREATE VIEW t2s_xsyn2.borrowers AS SELECT customer_id AS borrower_key, customer_number AS borrower_ref_no, customer_name AS borrower_title, party_type AS party_variety, customer_type_code AS borrower_variety_ref, customer_type_name AS borrower_variety_title, status_code AS condition_ref, status_name AS condition_title, segment_code AS segment_ref, segment_name AS segment_title, branch_id AS outlet_key, relationship_manager_id AS relationship_manager_key, kyc_status AS kyc_condition, aml_status AS aml_condition, risk_level AS exposure_tier, is_pep AS is_pep, is_blacklisted AS is_blacklisted, is_resident AS is_resident, country_code AS country_ref, onboarded_date AS onboarded_day, closed_date AS ended_day, province AS region, district AS area FROM t2s.customers;
CREATE VIEW t2s_xsyn2.natural_persons AS SELECT customer_id AS borrower_key, gender AS gender, birth_year AS birth_year, age AS age, marital_status AS marital_condition, dependants_count AS dependants_tally, education_level AS education_tier, occupation AS occupation, employer_name AS employer_title, employment_type AS job_variety, monthly_income AS monthly_earnings, income_currency AS earnings_money_unit FROM t2s.individuals;
CREATE VIEW t2s_xsyn2.firms AS SELECT customer_id AS borrower_key, org_name AS org_title, legal_form AS legal_form, industry_code AS industry_ref, industry_sector AS industry_sector, establishment_date AS establishment_day, employee_count AS worker_tally, annual_revenue AS annual_revenue, revenue_currency AS revenue_money_unit FROM t2s.organizations;
CREATE VIEW t2s_xsyn2.plans AS SELECT product_id AS plan_key, product_code AS plan_ref, product_name AS plan_title, product_type_code AS plan_variety_ref, product_type_name AS plan_variety_title, category AS class, currency_code AS money_unit_ref, amortization_type AS amortization_variety, requires_collateral AS requires_security, requires_guarantor AS requires_cosigner, min_credit_score AS min_credit_rating, max_dti_ratio AS max_dti_ratio, max_ltv_ratio AS max_ltv_ratio, launch_date AS launch_day, discontinue_date AS discontinue_day, status AS condition, annual_rate AS annual_pct, min_amount AS min_money, max_amount AS max_money, min_term_months AS min_duration_months, max_term_months AS max_duration_months FROM t2s.products;
CREATE VIEW t2s_xsyn2.facility_proposals AS SELECT application_id AS proposal_key, application_no AS proposal_no, customer_id AS borrower_key, product_id AS plan_key, branch_id AS outlet_key, loan_officer_id AS facility_officer_key, status_code AS condition_ref, status_name AS condition_title, channel AS route, requested_amount AS requested_money, requested_term_months AS requested_duration_months, currency_code AS money_unit_ref, purpose_category AS purpose_class, declared_income AS declared_earnings, dti_ratio AS dti_ratio, approved_amount AS approved_money, approved_term_months AS approved_duration_months, approved_rate AS approved_pct, credit_score AS credit_rating, decision_level AS verdict_tier, submitted_date AS submitted_day, decided_date AS decided_day, rejection_reason AS rejection_cause FROM t2s.loan_applications;
CREATE VIEW t2s_xsyn2.facilities AS SELECT loan_id AS facility_key, loan_number AS facility_ref_no, application_id AS proposal_key, customer_id AS borrower_key, product_id AS plan_key, branch_id AS outlet_key, loan_officer_id AS facility_officer_key, status_code AS condition_ref, status_name AS condition_title, is_active_portfolio AS is_active_portfolio, currency_code AS money_unit_ref, principal_amount AS capital_money, interest_rate AS yield_pct, penalty_rate AS surcharge_pct, effective_rate AS effective_pct, term_months AS duration_months, amortization_type AS amortization_variety, contract_date AS contract_day, disbursement_date AS disbursement_day, first_payment_date AS first_remittance_day, maturity_date AS maturity_day, closed_date AS ended_day, disbursed_amount AS disbursed_money, principal_outstanding AS capital_unpaid, interest_outstanding AS yield_unpaid, penalty_outstanding AS surcharge_unpaid, fee_outstanding AS fee_unpaid, total_outstanding AS overall_unpaid, principal_paid AS capital_settled, interest_paid AS yield_settled, penalty_paid AS surcharge_settled, fee_paid AS fee_settled, written_off_amount AS written_off_money, overdue_principal AS late_capital, overdue_interest AS late_yield, days_past_due AS day_count_behind_owed, max_days_past_due AS max_day_count_behind_owed, dpd_bucket AS dpd_bucket, classification_code AS classification_ref, classification_name AS classification_title, provision_rate AS provision_pct, is_npl AS is_npl, is_restructured AS is_restructured, restructure_count AS restructure_tally, last_payment_date AS last_remittance_day, fx_rate_to_mnt AS fx_pct_to_mnt, principal_amount_mnt AS capital_money_mnt, principal_outstanding_mnt AS capital_unpaid_mnt, total_outstanding_mnt AS overall_unpaid_mnt FROM t2s.loans;
CREATE VIEW t2s_xsyn2.facility_schedule AS SELECT loan_id AS facility_key, installment_no AS installment_no, due_date AS owed_day, principal_due AS capital_owed, interest_due AS yield_owed, total_due AS overall_owed, principal_paid AS capital_settled, interest_paid AS yield_settled, penalty_charged AS surcharge_charged, penalty_paid AS surcharge_settled, status AS condition, paid_date AS settled_day, days_past_due AS day_count_behind_owed, schedule_version AS schedule_version FROM t2s.loan_schedule;
CREATE VIEW t2s_xsyn2.facility_remittances AS SELECT payment_id AS remittance_key, payment_no AS remittance_no, loan_id AS facility_key, customer_id AS borrower_key, branch_id AS outlet_key, currency_code AS money_unit_ref, amount AS money, payment_date AS remittance_day, payment_method AS remittance_method, payment_type AS remittance_variety, allocated_principal AS allocated_capital, allocated_interest AS allocated_yield, allocated_penalty AS allocated_surcharge, allocated_fee AS allocated_fee, unallocated_amount AS unallocated_money, status AS condition FROM t2s.loan_payments;
CREATE VIEW t2s_xsyn2.facility_dpd_history AS SELECT loan_id AS facility_key, snapshot_date AS snapshot_day, days_past_due AS day_count_behind_owed, dpd_bucket AS dpd_bucket, overdue_principal AS late_capital, overdue_interest AS late_yield, overdue_penalty AS late_surcharge, total_outstanding AS overall_unpaid, classification_code AS classification_ref FROM t2s.loan_dpd_history;
CREATE VIEW t2s_xsyn2.facility_charges AS SELECT loan_id AS facility_key, charge_type AS charge_variety, charge_code AS charge_ref, charge_name AS charge_title, currency_code AS money_unit_ref, amount AS money, charged_date AS charged_day, paid_amount AS settled_money, waived_amount AS waived_money, status AS condition, days_overdue AS day_count_late FROM t2s.loan_charges;
CREATE VIEW t2s_xsyn2.facility_restructures AS SELECT loan_id AS facility_key, restructure_no AS restructure_no, restructure_type AS restructure_variety, reason AS cause, old_principal AS old_capital, new_principal AS new_capital, old_rate AS old_pct, new_rate AS new_pct, old_term_months AS old_duration_months, new_term_months AS new_duration_months, old_maturity_date AS old_maturity_day, new_maturity_date AS new_maturity_day, effective_date AS effective_day, status AS condition FROM t2s.loan_restructures;
CREATE VIEW t2s_xsyn2.facility_writeoffs AS SELECT loan_id AS facility_key, writeoff_date AS writeoff_day, principal_amount AS capital_money, interest_amount AS yield_money, penalty_amount AS surcharge_money, fee_amount AS fee_money, total_amount AS overall_money, writeoff_type AS writeoff_variety, recovered_amount AS recovered_money FROM t2s.loan_writeoffs;
CREATE VIEW t2s_xsyn2.securities AS SELECT collateral_id AS security_key, collateral_number AS security_ref_no, collateral_type_code AS security_variety_ref, collateral_type_name AS security_variety_title, collateral_category AS security_class, owner_customer_id AS owner_borrower_key, branch_id AS outlet_key, market_value AS market_worth, forced_sale_value AS forced_sale_worth, accepted_value AS accepted_worth, currency_code AS money_unit_ref, valuation_date AS valuation_day, next_valuation_date AS next_valuation_day, is_insured AS is_insured, encumbrance_status AS encumbrance_condition, status AS condition FROM t2s.collaterals;
CREATE VIEW t2s_xsyn2.facility_securities AS SELECT loan_id AS facility_key, collateral_id AS security_key, currency_code AS money_unit_ref, allocated_amount AS allocated_money, ltv_ratio AS ltv_ratio, pledge_date AS pledge_day, release_date AS release_day, status AS condition FROM t2s.loan_collaterals;
CREATE VIEW t2s_xsyn2.facility_cosigners AS SELECT loan_id AS facility_key, guarantor_id AS cosigner_key, guarantor_type AS cosigner_variety, is_existing_customer AS is_existing_borrower, guarantor_customer_id AS cosigner_borrower_key, currency_code AS money_unit_ref, guarantee_amount AS guarantee_money, guarantee_pct AS guarantee_pct, liability_type AS liability_variety, valid_from AS valid_from, valid_to AS valid_to, called_date AS called_day, called_amount AS called_money, recovered_amount AS recovered_money, status AS condition FROM t2s.loan_guarantors;
CREATE VIEW t2s_xsyn2.ledgers AS SELECT account_id AS ledger_key, customer_id AS borrower_key, branch_id AS outlet_key, product_id AS plan_key, account_type_code AS ledger_variety_ref, account_type_name AS ledger_variety_title, currency_code AS money_unit_ref, current_balance AS current_holding, available_balance AS available_holding, hold_amount AS hold_money, status AS condition, is_dormant AS is_dormant, opened_date AS started_day, closed_date AS ended_day, last_transaction_date AS last_movement_day FROM t2s.accounts;
CREATE VIEW t2s_xsyn2.movements AS SELECT transaction_id AS movement_key, transaction_no AS movement_no, account_id AS ledger_key, customer_id AS borrower_key, branch_id AS outlet_key, transaction_type_code AS movement_variety_ref, transaction_type_name AS movement_variety_title, category AS class, channel_code AS route_ref, channel_name AS route_title, status_code AS condition_ref, direction AS direction, amount AS money, fee_amount AS fee_money, currency_code AS money_unit_ref, amount_mnt AS money_mnt, transaction_date AS movement_day, value_date AS worth_day FROM t2s.transactions;
CREATE VIEW t2s_xsyn2.ledger_holdings_monthly AS SELECT account_id AS ledger_key, balance_date AS holding_day, opening_balance AS opening_holding, total_debit AS overall_debit, total_credit AS overall_credit, closing_balance AS closing_holding, transaction_count AS movement_tally, currency_code AS money_unit_ref, closing_balance_mnt AS closing_holding_mnt FROM t2s.account_balances_monthly;
CREATE VIEW t2s_xsyn2.savings AS SELECT deposit_id AS saving_key, deposit_number AS saving_ref_no, account_id AS ledger_key, customer_id AS borrower_key, product_id AS plan_key, branch_id AS outlet_key, currency_code AS money_unit_ref, deposit_type AS saving_variety, principal_amount AS capital_money, current_balance AS current_holding, interest_rate AS yield_pct, interest_method AS yield_method, term_months AS duration_months, accrued_interest AS accrued_yield, paid_interest AS settled_yield, withholding_tax_paid AS withholding_tax_settled, opened_date AS started_day, maturity_date AS maturity_day, closed_date AS ended_day, auto_renew AS auto_renew, renewal_count AS renewal_tally, is_pledged AS is_pledged, status AS condition, current_balance_mnt AS current_holding_mnt FROM t2s.deposits;
CREATE VIEW t2s_xsyn2.collection_files AS SELECT case_id AS file_key, case_no AS file_no, loan_id AS facility_key, customer_id AS borrower_key, branch_id AS outlet_key, stage_code AS stage_ref, stage_name AS stage_title, currency_code AS money_unit_ref, opened_date AS started_day, dpd_at_open AS dpd_at_open, current_dpd AS current_dpd, outstanding_at_open AS unpaid_at_open, current_outstanding AS current_unpaid, overdue_amount AS late_money, collected_amount AS collected_money, assigned_to AS assigned_to, agency_code AS agency_ref, agency_name AS agency_title, priority AS priority, status AS condition, closed_date AS ended_day, close_reason AS close_cause FROM t2s.collection_cases;
CREATE VIEW t2s_xsyn2.collection_activities AS SELECT action_id AS activity_key, case_id AS file_key, action_code AS activity_ref, action_name AS activity_title, channel AS route, action_date AS activity_day, performed_by AS performed_by, agency_code AS agency_ref, contact_result AS contact_result, cost_amount AS cost_money FROM t2s.collection_actions;
CREATE VIEW t2s_xsyn2.collection_promises AS SELECT promise_id AS promise_key, case_id AS file_key, currency_code AS money_unit_ref, promised_amount AS promised_money, promised_date AS promised_day, paid_amount AS settled_money, paid_date AS settled_day, status AS condition FROM t2s.collection_promises;
CREATE VIEW t2s_xsyn2.credit_ratings AS SELECT score_id AS rating_key, customer_id AS borrower_key, application_id AS proposal_key, model_code AS model_ref, model_name AS model_title, score AS rating, risk_grade_code AS exposure_grade_ref, risk_grade_name AS exposure_grade_title, pd_estimate AS pd_estimate, decision_hint AS verdict_hint, score_type AS rating_variety, scored_date AS scored_day FROM t2s.credit_scores;
CREATE VIEW t2s_xsyn2.aml_warnings AS SELECT alert_id AS warning_key, alert_no AS warning_no, rule_code AS rule_ref, rule_name AS rule_title, customer_id AS borrower_key, alert_amount AS warning_money, currency_code AS money_unit_ref, severity AS severity, status AS condition, detected_date AS detected_day, closed_date AS ended_day, str_reported AS str_reported FROM t2s.aml_alerts;
CREATE VIEW t2s_xsyn2.gl_entries AS SELECT entry_no AS entry_no, line_no AS line_no, posting_date AS posting_day, period_code AS period_ref, fiscal_year AS fiscal_year, branch_id AS outlet_key, journal_code AS journal_ref, journal_name AS journal_title, account_code AS ledger_ref, account_name_mn AS ledger_title_mn, account_type AS ledger_variety, dr_cr AS dr_cr, amount AS money, currency_code AS money_unit_ref, amount_mnt AS money_mnt, source_system AS source_system, entry_status AS entry_condition FROM t2s.gl_entries;
CREATE VIEW t2s_xsyn2.exchange_pcts AS SELECT currency_code AS money_unit_ref, rate_date AS pct_day, buy_rate AS buy_pct, sell_rate AS sell_pct, mid_rate AS mid_pct FROM t2s.exchange_rates;
GRANT USAGE ON SCHEMA t2s_xsyn2 TO t2s_bot; GRANT SELECT ON ALL TABLES IN SCHEMA t2s_xsyn2 TO t2s_bot;
